9	func (s *APIV1Service) listMemosByID(ctx context.Context, memoIDs []int32) (map[int32]*store.Memo, error) {
10		if len(memoIDs) == 0 {
11			return map[int32]*store.Memo{}, nil
12		}
13	
14		uniqueMemoIDs := make([]int32, 0, len(memoIDs))
15		seenMemoIDs := make(map[int32]struct{}, len(memoIDs))
16		for _, memoID := range memoIDs {
17			if _, seen := seenMemoIDs[memoID]; seen {
18				continue
19			}
20			seenMemoIDs[memoID] = struct{}{}
21			uniqueMemoIDs = append(uniqueMemoIDs, memoID)
22		}
23	
24		memos, err := s.Store.ListMemos(ctx, &store.FindMemo{IDList: uniqueMemoIDs})
25		if err != nil {
26			return nil, err
27		}
28	
29		memosByID := make(map[int32]*store.Memo, len(memos))
30		for _, memo := range memos {
31			memosByID[memo.ID] = memo
32		}
33		return memosByID, nil
34	}
